def resolve(path, cwd, links):
    def split(p):
        return [c for c in p.split('/') if c not in ('', '.')]

    if path.startswith('/'):
        current = []
        components = split(path)
    else:
        current = split(cwd)
        components = split(path)

    queue = components[:]
    link_count = 0

    while queue:
        comp = queue.pop(0)
        if comp == '..':
            if current:
                current.pop()
        else:
            current.append(comp)
            candidate = '/' + '/'.join(current)
            if candidate in links:
                link_count += 1
                if link_count > 8:
                    return None
                target = links[candidate]
                # base directory containing the link is 'current' before appending comp
                base_dir = current[:-1]
                current.pop()  # remove the appended comp; we're replacing it with link target

                if target.startswith('/'):
                    new_current = []
                    new_components = split(target)
                else:
                    new_current = base_dir[:]
                    new_components = split(target)

                current = new_current
                queue = new_components + queue

    return '/' + '/'.join(current) if current else '/'

